// Share only public query data. Weather is de-duplicated across journey legs.
function v20ThinWeather(w){if(!w)return null;const h=w.hourly;if(!h)return v20Copy(w);let start=Math.max(0,h.time.findIndex(t=>t>=(w.current?.time||''))-1);const hourly={};for(const [k,v] of Object.entries(h))hourly[k]=Array.isArray(v)?v.slice(start,start+72):v;return {place:w.place,current:w.current,current_units:w.current_units,hourly,hourly_units:w.hourly_units,fetchedAt:w.fetchedAt,timezone:'Asia/Shanghai'}}
function v20PackSnapshot(s){const weatherPool=[],weatherIndex=new Map();const put=w=>{if(!w)return null;const thin=v20ThinWeather(w),key=JSON.stringify(thin);if(!weatherIndex.has(key)){weatherIndex.set(key,weatherPool.length);weatherPool.push(thin)}return weatherIndex.get(key)};const clean={version:3,mode:s.mode,at:s.at,origin:s.origin,destination:s.destination,vias:s.vias,transport:s.transport,planned:s.planned,created:s.created,weatherRef:put(s.weather),weatherPool,plans:[]};const fields=['id','journeyId','leg','origin','destination','vias','transport','mode','at','planned','created','queryTime','snapshotVersion','roundTrip','duration','distance','coords','label','unavailable','blocked','segments','arrivalText','referenceMinutes','estimateBasis','walkMeters','boarding','alighting','walkSnaps','routeProvider','routeFetchedAt','routeSource','probabilitySnapshot','localRiskSnapshots','geometryBasis'];for(const p of s.plans||[]){const q=Object.fromEntries(fields.filter(k=>p[k]!==undefined).map(k=>[k,v20Copy(p[k])]));q.weatherRef=put(p.queryWeather);q.roadNames=(p.roadNames||[]).slice(0,40);q.walkSteps=(p.walkSteps||[]).slice(0,150);if(p.geometry){const cs=p.geometry.coordinates,stride=Math.max(1,Math.ceil(cs.length/120));q.geometry={type:'LineString',coordinates:cs.filter((c,i)=>i===0||i===cs.length-1||i%stride===0).map(c=>c.map(n=>Number(n.toFixed(6))))}}clean.plans.push(q)}return clean}
function v20UnpackSnapshot(x){if(x?.version!==3||!['now','history'].includes(x.mode)||!Array.isArray(x.plans)||x.plans.length>10||!Array.isArray(x.weatherPool)||x.weatherPool.length>12)throw Error('分享数据结构无效');for(const w of x.weatherPool){if(typeof w?.place!=='string'||w.place.length>300||(w.hourly&&(!Array.isArray(w.hourly.time)||w.hourly.time.length>72||w.hourly.time.some(t=>typeof t!=='string'||!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(t)))))throw Error('天气快照无效');if(w.current&&['temperature_2m','precipitation','wind_speed_10m'].some(k=>w.current[k]!=null&&!Number.isFinite(w.current[k])))throw Error('天气数值无效')}const plans=x.plans.map(p=>{if(typeof p.origin!=='string'||typeof p.destination!=='string'||p.origin.length>300||p.destination.length>300||!Array.isArray(p.vias)||p.vias.length>10||p.vias.some(v=>typeof v!=='string'))throw Error('行程快照无效');if(p.geometry&&(!Array.isArray(p.geometry.coordinates)||p.geometry.coordinates.length>160||p.geometry.coordinates.some(c=>!Array.isArray(c)||c.length!==2||!c.every(Number.isFinite)||c[0]<113.5||c[0]>114.8||c[1]<22.2||c[1]>23.1)))throw Error('地图快照无效');if(p.coords&&(!Array.isArray(p.coords)||p.coords.length>12||p.coords.some(c=>!c||![c.lat,c.lon].every(Number.isFinite))))throw Error('点位无效');if(p.segments&&(!Array.isArray(p.segments)||p.segments.length>20||p.segments.some(g=>!/^\d+(?:&\d+)?$/.test(String(g.line))||!Number.isFinite(g.stops)||g.stops<0||g.stops>100)))throw Error('轨道区段无效');if(p.probabilitySnapshot&&(!Number.isFinite(p.probabilitySnapshot.percent)||p.probabilitySnapshot.percent<0||p.probabilitySnapshot.percent>100||!Number.isFinite(p.probabilitySnapshot.n)||p.probabilitySnapshot.n<10))throw Error('概率快照无效');if(p.referenceMinutes&&(!Array.isArray(p.referenceMinutes)||p.referenceMinutes.some(n=>!Number.isFinite(n)||n<0)))throw Error('时长范围无效');if(p.segments)for(const g of p.segments)if(g.closure){const official=D.events.find(e=>e.record_id===g.closure.record_id);if(!official)throw Error('公告来源无效');g.closure=v20Copy(official)}p.duration=Number.isFinite(p.duration)&&p.duration>=0?p.duration:null;p.distance=Number.isFinite(p.distance)&&p.distance>=0?p.distance:null;return {...p,queryWeather:v20Copy(x.weatherPool[p.weatherRef]||null),feedbackRecords:[],feedbackCaptured:true}});return {...x,plans,weather:v20Copy(x.weatherPool[x.weatherRef]||plans[0]?.queryWeather||null),feedbackRecords:[]}}
function v20B64(bytes){let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function v20UnB64(s){return Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))}
